#include <iostream>
#include <string>

class Date {
public:
    Date(int m, int d, int y) : month(m), day(d), year(y) {
        std::cout << "Date constructor: " << month << '/' << day << '/' << year << '\n';
    }
    // Default copy constructor is synthesized by the compiler
    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }
    ~Date() {
        std::cout << "Date destructor: " << month << '/' << day << '/' << year << '\n';
    }
private:
    int month;
    int day;
    int year;
};

class Employee {
public:
    Employee(const std::string& first, const std::string& last,
             const Date& dob, const Date& doh)
        : firstName(first), lastName(last), birthDate(dob), hireDate(doh) {
        std::cout << "Employee constructor: " << firstName << ' ' << lastName << '\n';
    }
    void print() const {
        std::cout << lastName << ", " << firstName << " Hired: ";
        hireDate.print();
        std::cout << " Birthday: ";
        birthDate.print();
        std::cout << '\n';
    }
    ~Employee() {
        std::cout << "Employee destructor: " << lastName << ", " << firstName << '\n';
    }
private:
    std::string firstName;
    std::string lastName;
    const Date birthDate;
    const Date hireDate;
};

int main() {
    {
        Date birth(7, 24, 1949);
        Date hire(3, 12, 1988);
        Employee emp("Bob", "Blue", birth, hire);
        emp.print();
    }
    return 0;
}

#include <iostream>

class Member {
public:
    explicit Member(int id) : memberId(id) {
        std::cout << "Member " << memberId << " constructed\n";
    }
    ~Member() {
        std::cout << "Member " << memberId << " destructed\n";
    }
private:
    int memberId;
};

class Container {
public:
    Container() : m1(1), m2(2) {
        std::cout << "Container constructed\n";
    }
    ~Container() {
        std::cout << "Container destructed\n";
    }
private:
    Member m1;
    Member m2;
};

int main() {
    std::cout << "-- Entering block --\n";
    {
        Container c;
    }
    std::cout << "-- Exited block --\n";
    return 0;
}
